on conflict (id) do update
   set type = excluded.type,
       name = excluded.name,
       description = excluded.description,
       geom = excluded.geom,
       access_point = excluded.access_point,
       attributes = excluded.attributes
 where p.owner_id = private.editorial_id();

update public.places
   set deleted_at = now()
